// === /js/engine/interaction/switchInteraction.js ===
class SwitchInteraction extends AbstractInteraction {
    constructor(code) {
        super();
        this._code         = code;
        this._state        = false;
        this._stateTimer   = 0;
        this._done         = false;
        this._lastInstance = null;
        this.setModeOnce();
    }

    get code() {
        return this._code;
    }

    setModeToggle(minOnTime, minOffTime) {
        this._mode       = 'toggle';
        this._minOnTime  = minOnTime;
        this._minOffTime = minOffTime;
        return this;
    }

    setModeTimed(minOnTime, minOffTime) {
        this._mode       = 'timed';
        this._minOnTime  = minOnTime;
        this._minOffTime = minOffTime;
        return this;
    }

    setModeOnce() {
        this._mode       = 'once';
        this._minOnTime  = null;
        this._minOffTime = null;
        return this;
    }

    triggered(instance) {
        if (this._done) {
            return;
        }

        const minTime = ((this._state) ? this._minOnTime : this._minOffTime);
        if ((this._mode !== 'once') && (this._stateTimer < minTime)) {
            return;
        }

        if ((this._mode === 'timed') && this._state) {
            return;
        }

        const previous = {state: this._state, stateTimer: this._stateTimer, done: this._done};
        this._state      = !this._state;
        this._stateTimer = 0;
        if (this._mode === 'once') {
            this._done = true;
        }

        if (this._state) {
            // A refused ON (busy mover) spends nothing: the switch stays usable
            if (this._triggerOn(instance) === false) {
                this._state      = previous.state;
                this._stateTimer = previous.stateTimer;
                this._done       = previous.done;
                return;
            }
        } else {
            this._triggerOff(instance);
        }
        this._lastInstance = instance;
    }

    update(dt) {
        this._stateTimer += dt;

        if ((this._mode === 'timed') && this._state && (this._stateTimer >= this._minOnTime)) {
            this._state      = false;
            this._stateTimer = 0;
            this._triggerOff(this._lastInstance);
        }
    }

    exportState() {
        return {
            state:   this._state,
            onTimer: this._stateTimer,
            done:    this._done,
        };
    }

    importState(state) {
        this._state      = (state.state === true);
        this._stateTimer = state.onTimer;
        this._done       = (state.done === true);
    }

    // Returns whether the action took (false = refuse the press, see triggered).
    _triggerOn(instance) {
        console.log('[SwitchInteraction] ' + instance.getCode() + ' -> ON');

        return true;
    }

    _triggerOff(instance) {
        console.log('[SwitchInteraction] ' + instance.getCode() + ' -> OFF');
    }
}

