// === /js/engine/loader.js ===
class Loader {
    constructor() {
        this._callback            = null;
        this._loaded              = false;
        this._batching            = false;
        this._textureLoader       = new TextureLoader(() => this._checkFullyLoaded());
        this._animatedModelLoader = new AnimatedModelLoader(() => this._checkFullyLoaded());
        this._staticModelLoader   = new StaticModelLoader(() => this._checkFullyLoaded());
        this._object3dLoader      = new Object3dLoader(() => this._checkFullyLoaded());
        this._instanceLoader      = new InstanceLoader(() => this._checkFullyLoaded());
        this._interactionLoader   = new InteractionLoader(() => this._checkFullyLoaded());
        this._worldLoader         = new WorldLoader(() => this._checkFullyLoaded());
    }

    reset() {
        this._loaded   = false;
        this._callback = null;
        this._batching = false;
        this._worldLoader.reset();
        this._interactionLoader.reset();
        this._instanceLoader.reset();
        this._object3dLoader.reset();
        this._staticModelLoader.reset();
        this._animatedModelLoader.reset();
        this._textureLoader.reset();
    }

    // Suspends the global check during a synchronous in-memory build, which
    // would otherwise run finalizeInit on everything after each loadFromData
    beginBatch() {
        this._batching = true;
    }

    endBatch() {
        this._batching = false;
        this._checkFullyLoaded();
    }

    setCallback(callback) {
        this._callback = callback;
        if (this._loaded) {
            callback();
        }
    }

    // Once consumed, so entities registered at runtime don't re-invoke it
    clearCallback() {
        this._callback = null;
        return this;
    }

    animatedModels() {
        return this._animatedModelLoader;
    }

    staticModels() {
        return this._staticModelLoader;
    }

    instances() {
        return this._instanceLoader;
    }

    interactions() {
        return this._interactionLoader;
    }

    objects() {
        return this._object3dLoader;
    }

    textures() {
        return this._textureLoader;
    }

    world() {
        return this._worldLoader;
    }

    _checkFullyLoaded() {
        if (this._batching) {
            return false;
        }
        if (!this._instanceLoader.isLoaded()) {
            return false;
        }
        if (!this._interactionLoader.isLoaded()) {
            return false;
        }
        if (!this._object3dLoader.isLoaded()) {
            return false;
        }
        if (!this._textureLoader.isLoaded()) {
            return false;
        }
        if (!this._animatedModelLoader.isLoaded()) {
            return false;
        }
        if (!this._staticModelLoader.isLoaded()) {
            return false;
        }
        if (!this._worldLoader.isLoaded()) {
            return false;
        }

        this._textureLoader.finalizeInit();
        this._animatedModelLoader.finalizeInit();
        this._staticModelLoader.finalizeInit();
        this._object3dLoader.finalizeInit();
        this._instanceLoader.finalizeInit();
        this._interactionLoader.finalizeInit();
        this._worldLoader.finalizeInit();

        this._loaded = true;

        if (this._callback) {
            this._callback();
        }
    }
}

