// === /js/engine/animation/animationPlayer.js ===
/**
 * Plays animation clips on a pose: time, speed, loop, the events crossed,
 * the cross-fade from one clip to the next (the clip left keeps playing on a
 * second pose, blended out along a smoothstep) and the root motion (the
 * horizontal travel of a root joint, taken out of the pose and handed to the
 * game). Allocates nothing by frame.
 */
class AnimationPlayer {
    /**
     * @param {SkeletonPose} pose - written at each advance
     */
    constructor(pose) {
        this._pose         = pose;
        this._fadePose     = new SkeletonPose(pose.getSkeleton());
        this._current      = AnimationPlayer._track();
        this._previous     = AnimationPlayer._track();
        this._fadeDuration = 0;
        this._fadeElapsed  = 0;
        this._crossed      = [];
        this._rootJoint    = null;
        this._rootByClip   = new Map();
        this._rootMotion   = new Float32Array(AnimationPlayer.ROOT_MOTION_SIZE);
        this._rootSample   = new Float32Array(Skeleton.TRANSLATION_SIZE);
        this._rootCursor   = AnimationSampler.createCursor();
    }

    /**
     * The joint whose horizontal travel (x, z of its translation) is root motion: taken out of the pose, which keeps
     * the joint's x and z of the clip's start, and handed by getRootMotion.
     *
     * @param {int|null} joint - null: none
     */
    setRootMotion(joint) {
        this._rootJoint = joint;
        this._rootByClip.clear();
        this._rootMotion.fill(0);
        this._anchorRoot(this._current);
        this._anchorRoot(this._previous);

        return this;
    }

    /**
     * The travel of the root joint over the last advance, blended as the poses are during a cross-fade.
     *
     * @param {Float32Array} out - [dx, dz] in the model's space, metres
     */
    getRootMotion(out) {
        out[0] = this._rootMotion[0];
        out[1] = this._rootMotion[1];

        return out;
    }

    /**
     * Starts a clip at once.
     *
     * @param {AnimationClip} clip
     * @param {{time?: number, speed?: number, loop?: boolean}} options - time below 0 = a delay holding the first
     *        pose; speed 1 by default
     */
    play(clip, options = {}) {
        this._start(this._current, clip, options);
        this._fadeDuration = 0;
        this._previous.clip = null;

        return this;
    }

    /**
     * Starts a clip, the one playing fading out over duration seconds.
     *
     * @param {AnimationClip} clip
     * @param {number}        duration
     * @param {{time?: number, speed?: number, loop?: boolean}} options
     */
    crossFadeTo(clip, duration, options = {}) {
        if ((this._current.clip === null) || (duration <= 0)) {
            return this.play(clip, options);
        }
        const left = this._current;

        this._current  = this._previous;
        this._previous = left;
        this._start(this._current, clip, options);
        this._fadeDuration = duration;
        this._fadeElapsed  = 0;

        return this;
    }

    getClip() {
        return this._current.clip;
    }

    getTime() {
        return this._current.time;
    }

    isFinished() {
        const track = this._current;

        return ((track.clip !== null) && !track.loop && (track.time >= track.clip.getDuration()));
    }

    isFading() {
        return (this._fadeDuration > 0);
    }

    /**
     * Moves the time on and writes the pose; the events are those of the clip playing, not of the one fading out.
     *
     * @param {number}           dt        - seconds
     * @param {AnimationEvent[]} eventsOut - emptied, then filled in time order
     */
    advance(dt, eventsOut) {
        const current = this._current;

        eventsOut.length = 0;
        this._rootMotion.fill(0);
        if (current.clip === null) {
            return eventsOut;
        }
        this._step(current, dt, eventsOut);
        this._pose.reset();
        current.clip.applyTo(this._pose, current.time, current.cursors);
        this._takeRootMotion(current, this._pose, 1);
        if (this._fadeDuration > 0) {
            this._fade(dt);
        }

        return eventsOut;
    }

    _fade(dt) {
        const previous = this._previous;

        this._fadeElapsed += dt;
        if (this._fadeElapsed >= this._fadeDuration) {
            this._fadeDuration = 0;
            previous.clip = null;
            return;
        }
        this._step(previous, dt, null);
        this._fadePose.reset();
        previous.clip.applyTo(this._fadePose, previous.time, previous.cursors);
        // Smoothstep: the weights start and end with no speed, the blend adds no jump of its own.
        const share = (this._fadeElapsed / this._fadeDuration);
        const eased = ((3 * share * share) - (2 * share * share * share));
        this._rootMotion[0] *= eased;
        this._rootMotion[1] *= eased;
        this._takeRootMotion(previous, this._fadePose, (1 - eased));
        this._pose.blend(this._fadePose, (1 - eased));
    }

    /**
     * Adds the root joint's travel since the track's last step (whole turns of a loop included) to the root motion,
     * weighted, then puts the joint back on its x and z of the clip's start.
     */
    _takeRootMotion(track, pose, weight) {
        const root = this._rootOf(track.clip);
        if (root === null) {
            return;
        }
        const translation = pose.getTranslation();
        const x           = (this._rootJoint * Skeleton.TRANSLATION_SIZE);
        const z           = (x + AnimationPlayer.Z_COMPONENT);
        const dx          = ((translation[x] - track.rootX) + (track.turns * (root.endX - root.startX)));
        const dz          = ((translation[z] - track.rootZ) + (track.turns * (root.endZ - root.startZ)));

        this._rootMotion[0] += (dx * weight);
        this._rootMotion[1] += (dz * weight);
        track.rootX    = translation[x];
        track.rootZ    = translation[z];
        translation[x] = root.startX;
        translation[z] = root.startZ;
    }

    /**
     * The root joint's translation channel in a clip and its x, z at the clip's start and end, kept per clip; null
     * without root motion or when the clip does not move the root joint.
     */
    _rootOf(clip) {
        if (this._rootJoint === null) {
            return null;
        }
        if (!this._rootByClip.has(clip)) {
            this._rootByClip.set(clip, this._measureRoot(clip));
        }

        return this._rootByClip.get(clip);
    }

    _measureRoot(clip) {
        const channel = clip.getChannels().find((c) => ((c.getJoint() === this._rootJoint) && (c.getPath() === AnimationChannel.TRANSLATION)));
        if (channel === undefined) {
            return null;
        }
        const start  = this._sampleRoot(channel, 0);
        const startX = start[0];
        const startZ = start[AnimationPlayer.Z_COMPONENT];
        const end    = this._sampleRoot(channel, clip.getDuration());

        return Object.freeze({channel: channel, startX: startX, startZ: startZ, endX: end[0], endZ: end[AnimationPlayer.Z_COMPONENT]});
    }

    // A root translation channel at a time, in a buffer of the player (overwritten by the next call).
    _sampleRoot(channel, time) {
        channel.getSampler().sample(time, this._rootCursor, this._rootSample, 0);

        return this._rootSample;
    }

    // The track's root joint taken where its clip stands: no travel is counted for its next step.
    _anchorRoot(track) {
        const root = ((track.clip === null) ? null : this._rootOf(track.clip));
        if (root === null) {
            return;
        }
        const at = this._sampleRoot(root.channel, track.time);
        track.rootX = at[0];
        track.rootZ = at[AnimationPlayer.Z_COMPONENT];
    }

    // A looping clip reports the events of each turn, its start included.
    _step(track, dt, eventsOut) {
        const clip     = track.clip;
        const duration = clip.getDuration();
        let t0    = track.time;
        let t1    = (t0 + (dt * track.speed));
        let start = track.fresh;

        track.fresh = false;
        track.turns = 0;
        if (track.loop && (duration > 0)) {
            while (t1 > duration) {
                this._collect(clip, t0, duration, start, eventsOut);
                t0    = 0;
                t1   -= duration;
                start = true;
                track.turns++;
            }
        } else {
            t1 = Math.min(t1, duration);
        }
        this._collect(clip, t0, t1, start, eventsOut);
        track.time = t1;
    }

    _collect(clip, t0, t1, includeStart, eventsOut) {
        if (eventsOut === null) {
            return;
        }
        clip.eventsBetween(t0, t1, this._crossed, includeStart);
        for (const event of this._crossed) {
            eventsOut.push(event);
        }
    }

    static _track() {
        return {clip: null, cursors: null, cursorsByClip: new Map(), time: 0, speed: 1, loop: false, fresh: false, turns: 0, rootX: 0, rootZ: 0};
    }

    // Cursors kept per clip and per track: a clip played again reuses them.
    _start(track, clip, options) {
        if (!track.cursorsByClip.has(clip)) {
            track.cursorsByClip.set(clip, clip.createCursors());
        }
        track.clip    = clip;
        track.cursors = track.cursorsByClip.get(clip);
        track.time    = (options.time ?? 0);
        track.speed   = (options.speed ?? 1);
        track.loop    = (options.loop === true);
        track.fresh   = true;
        this._anchorRoot(track);
    }
}

// Root motion: [dx, dz]; z is the third component of a translation.
AnimationPlayer.ROOT_MOTION_SIZE = 2;
AnimationPlayer.Z_COMPONENT      = 2;

;
// === /js/engine/animation/animatedInstance.js ===
/**
 * An animated character in the world: its own copy of the model's geometry
 * (an Object3d), the engine Instance that places and draws it, its pose, its
 * player and the objects it handles. The game calls update at each frame (0
 * under a pause, to draw the pose still); the engine imposes no loop.
 *
 * An object taken (attach) follows a socket; one laid down (detach with a
 * place) goes to its place, then stays there. Either way it may move there
 * over a transition, from where it was, its speed rising and falling to zero:
 * never a jump.
 *
 * A mirrored instance (scene mirrored in x) negates x after the skinning; the
 * objects it handles must be built mirrored too, as any geometry of that scene.
 */
class AnimatedInstance {
    /**
     * Registers the geometry and the Instance in the loader; bind once the loader is ready.
     *
     * @param {AnimatedModel} model
     * @param {{materialColor?: function(object): number[], mirror?: boolean, position?: number[],
     *          rotation?: number[]}} options - materialColor: [r, g, b(, alpha)] 0-255 of a material (default its
     *          glTF color, ModelMesh.materialColor); rotation in degrees as Instance.setRotation
     */
    constructor(model, options = {}) {
        const materialColor = (options.materialColor ?? ModelMesh.materialColor);
        const pose          = new SkeletonPose(model.getSkeleton());

        this._model       = model;
        this._mirror      = (options.mirror === true);
        this._pose        = pose;
        this._player      = new AnimationPlayer(pose);
        this._objectId    = loader.objects().loadFromData(null, model.getMesh().toObjectData(model.getMaterials(), materialColor, this._mirror));
        this._instanceId  = loader.instances().loadFromData(null, {
            object:         this._objectId,
            position:       [...(options.position ?? [0, 0, 0])],
            rotation:       [...(options.rotation ?? [0, 0, 0])],
            trigger:        'none',
            keyframes:      [],
            collisionShape: 'none',
        });
        this._object      = null;
        this._instance    = null;
        this._placement   = Mat4.create();
        this._unplacement = Mat4.create();
        this._translation = new Float32Array(Skeleton.TRANSLATION_SIZE);
        this._orientation = new Float32Array(Skeleton.ROTATION_SIZE);
        this._rootMotion  = new Float32Array(AnimationPlayer.ROOT_MOTION_SIZE);
        this._handled     = [];
    }

    bind() {
        this._object   = loader.objects().get(this._objectId);
        this._instance = loader.instances().get(this._instanceId);
        this._refreshPlacement();

        return this;
    }

    getInstance() {
        return this._instance;
    }

    getPlayer() {
        return this._player;
    }

    getPose() {
        return this._pose;
    }

    /**
     * @param {number[]} position
     * @param {number[]} rotation - degrees, as Instance.setRotation
     */
    place(position, rotation) {
        this._instance.setRotation(rotation);
        this._instance.setPose(position, [0, 0, 0], [0, 0, 0]);
        this._refreshPlacement();

        return this;
    }

    /**
     * Plays the clips, poses the skeleton, writes the geometry, then moves the objects handled; one laid down is let
     * go once at its place.
     *
     * @param {number}           dt        - seconds
     * @param {AnimationEvent[]} eventsOut - the events crossed (AnimationPlayer.advance)
     */
    update(dt, eventsOut) {
        this._player.advance(dt, eventsOut);
        this._pose.computeWorld().computeSkinning();
        this._model.getMesh().skinInto(this._object, this._pose, this._mirror);
        this._instance.refreshWorldCenter();
        for (const handled of this._handled) {
            handled.elapsed = Math.min((handled.elapsed + dt), handled.duration);
            this._move(handled);
        }
        if (this._handled.some((handled) => AnimatedInstance._laid(handled))) {
            this._handled = this._handled.filter((handled) => !AnimatedInstance._laid(handled));
        }

        return eventsOut;
    }

    /**
     * Moves the instance by the root motion of the last update, turned as the character is (mirror included): the
     * travel the clips give the feet, so they do not slide on the ground.
     */
    applyRootMotion() {
        const motion = this._player.getRootMotion(this._rootMotion);
        const m      = this._placement;
        const dx     = (this._mirror ? -motion[0] : motion[0]);
        const dz     = motion[1];
        const x      = ((dx * m[0]) + (dz * m[AnimatedInstance.Z_ROW]));
        const y      = ((dx * m[1]) + (dz * m[AnimatedInstance.Z_ROW + 1]));
        const z      = ((dx * m[2]) + (dz * m[AnimatedInstance.Z_ROW + 2]));

        this._instance.translate(x, y, z);
        m[AnimatedInstance.TRANSLATION_ROW]     += x;
        m[AnimatedInstance.TRANSLATION_ROW + 1] += y;
        m[AnimatedInstance.TRANSLATION_ROW + 2] += z;

        return this;
    }

    /**
     * The instance follows the socket until detached, reaching it from where it is over the transition; its own
     * transform is replaced by a world matrix.
     *
     * @param {Instance} instance
     * @param {string}   socketName
     * @param {number}   transition - seconds, 0: at once
     */
    attach(instance, socketName, transition = 0) {
        this._handle(instance, this._model.getSocket(socketName), null, transition);

        return this;
    }

    /**
     * Lets the instance go: without a place it stays where it is; with one, it goes there over the transition, then
     * stays (an instance not held is laid there the same way).
     *
     * @param {Instance}          instance
     * @param {Float32Array|null} place      - in the model's space (Mat4), as the clips' events give it
     * @param {number}            transition - seconds, 0: at once
     */
    detach(instance, place = null, transition = 0) {
        this._handled = this._handled.filter((handled) => (handled.instance !== instance));
        if (place !== null) {
            this._handle(instance, null, this.toWorld(Mat4.create(), place), transition);
        }

        return this;
    }

    /**
     * @param {string}       name
     * @param {Float32Array} out  - the socket in the world (Mat4 layout)
     */
    socketMatrix(name, out) {
        const socket = this._model.getSocket(name);

        return this.toWorld(out, Mat4.multiply(out, socket.getOffset(), this._pose.getWorld(socket.getJoint())));
    }

    /**
     * A transform in the model's space (as the clips and their events give it) into the world.
     *
     * @param {Float32Array} out   - may be local
     * @param {Float32Array} local
     */
    toWorld(out, local) {
        if (this._mirror) {
            Mat4.mirrorX(out, local);
            return Mat4.multiply(out, out, this._placement);
        }

        return Mat4.multiply(out, local, this._placement);
    }

    /**
     * A transform in the world into the model's space: the inverse of toWorld (a place for detach, from the world).
     *
     * @param {Float32Array} out   - may be world
     * @param {Float32Array} world
     */
    toLocal(out, world) {
        Mat4.multiply(out, world, Mat4.invertRigid(this._unplacement, this._placement));

        return ((this._mirror) ? Mat4.mirrorX(out, out) : out);
    }

    // Buffers made here, once per taking or laying: the frames that move the instance allocate nothing.
    _handle(instance, socket, place, transition) {
        this._handled = this._handled.filter((handled) => (handled.instance !== instance));
        const from = Mat4.fromMatrix(Mat4.create(), Matrix.composeInstanceTransform(instance.getTransform()));
        const handled = {
            instance:        instance,
            socket:          socket,
            place:           place,
            elapsed:         0,
            duration:        Math.max(transition, 0),
            fromTranslation: Float32Array.of(from[AnimatedInstance.TRANSLATION_ROW], from[AnimatedInstance.TRANSLATION_ROW + 1], from[AnimatedInstance.TRANSLATION_ROW + 2]),
            fromRotation:    Quaternion.fromMat4(new Float32Array(Skeleton.ROTATION_SIZE), 0, from),
            translation:     new Float32Array(Skeleton.TRANSLATION_SIZE),
            rotation:        new Float32Array(Skeleton.ROTATION_SIZE),
            target:          Mat4.create(),
            world:           Mat4.create(),
            matrix:          new Matrix().identity(),
        };
        this._handled.push(handled);
        this._move(handled);
    }

    // Where the instance is now: its goal (the socket, or its place), or on the way from where it started.
    _move(handled) {
        const target = handled.target;
        if (handled.socket === null) {
            Mat4.copy(target, handled.place);
        } else {
            Mat4.multiply(target, handled.socket.getOffset(), this._pose.getWorld(handled.socket.getJoint()));
            this.toWorld(target, target);
        }
        let world = target;
        if (handled.elapsed < handled.duration) {
            const share = (handled.elapsed / handled.duration);
            const eased = ((3 * share * share) - (2 * share * share * share));
            const t     = handled.translation;
            for (let k = 0; k < Skeleton.TRANSLATION_SIZE; k++) {
                t[k] = (handled.fromTranslation[k] + ((target[AnimatedInstance.TRANSLATION_ROW + k] - handled.fromTranslation[k]) * eased));
            }
            Quaternion.fromMat4(handled.rotation, 0, target);
            Quaternion.slerp(handled.rotation, 0, handled.fromRotation, 0, handled.rotation, 0, eased);
            world = Mat4.fromTranslationRotationScale(handled.world, t, 0, handled.rotation, 0, AnimatedInstance.UNIT_SCALE, 0);
        }
        handled.instance.setWorldMatrix(Mat4.toMatrix(handled.matrix, world));
    }

    // A laying finished: the instance stays at its place, no longer moved.
    static _laid(handled) {
        return ((handled.socket === null) && (handled.elapsed >= handled.duration));
    }

    // The Instance's position and rotation as a Mat4 (Matrix.composeInstanceTransform without the animation deltas).
    _refreshPlacement() {
        this._translation.set(this._instance.getPosition());
        Quaternion.fromDegrees(this._orientation, 0, this._instance.getRotation());
        Mat4.fromTranslationRotationScale(this._placement, this._translation, 0, this._orientation, 0, AnimatedInstance.UNIT_SCALE, 0);
    }
}

AnimatedInstance.UNIT_SCALE      = Float32Array.of(1, 1, 1);
// Rows of a Mat4 (row vectors): the image of z, the translation.
AnimatedInstance.Z_ROW           = (2 * Mat4.ORDER);
AnimatedInstance.TRANSLATION_ROW = (3 * Mat4.ORDER);

