        this._isBlocked         = isBlocked;
        this._escapeAsBack      = false;
        this._items             = [];
        this._index             = -1;
        this._sideButtons       = [];
        this._sideIndex         = -1;
        this._sideEntry         = -1;
        this._bottomButtons     = [];
        this._bottomIndex       = -1;
        this._backButton        = null;
        this._onPage            = null;
        this._onSelect          = null;
        this._selectFirstTap    = false;
        this._tapStart          = null;
        this._horizontal        = false;
        this._grid              = null;
        this._onStart           = null;
        this._keyDownListener   = this._onKeyDown.bind(this);
        this._mouseMoveListener = this._onMouseMove.bind(this);
        this._mouseArmed        = false;
        this._pad               = new AppInputGamepad();
        this._padTimer          = null;
        this._padSeen           = false;
        this._padState          = {validate: false, back: false, start: false, pagePrev: false, pageNext: false};
        this._padHeldY          = {dir: 0, ms: 0};
        this._padHeldX          = {dir: 0, ms: 0};
