// === /js/doom/sound/doomSoundCatalog.js ===
/**
 * Generic resolver of a game's logical sound names — the SNDINFO table the
 * profile transcribes: name → {lump | alias | random[]} plus the per-sound
 * attributes ($limit, $pitchshift, $singular).
 *
 * Sounds resolve BY NAME only, never by sniffing lump headers (a map lump can
 * pass the DMX format test). A name the table does not carry degrades to null
 * — a game may not define every event, and a WAD may lack a lump the table
 * names (heretic.wad has no dssecret): silence, never a throw.
 */
class DoomSoundCatalog {
    // Chain guard: aliases and random groups reference other logical names, a
    // circular table must not hang the resolver.
    static MAX_CHAIN = 8;

    /**
     * @param {object} defs name → {lump?, alias?, random?, limit?, limitRange?, pitch?, singular?}
     */
    constructor(defs) {
        this._defs = defs;
    }

    /**
     * Every WAD lump the table references — what the sound system decodes when
     * a WAD is selected.
     *
     * @returns {string[]} unique lump names
     */
    lumpNames() {
        const names = new Set();
        for (const name of Object.keys(this._defs)) {
            const lump = this._defs[name].lump;
            if (lump !== undefined) {
                names.add(lump);
            }
        }

        return [...names];
    }

    /**
     * Resolves a logical name down to its lump, following aliases and picking
     * one entry of a $random group per call. An attribute set anywhere along
     * the chain wins over the target's (an alias inherits the limit of its
     * target when it sets none — the NearLimit -1 of the UZDoom $alias).
     *
     * @param {string} name e.g. 'weapons/pistol'
     * @returns {{lump: string, limit: number, limitRange: number, pitch: number|null, singular: boolean}|null}
     */
    resolve(name) {
        let lump       = null;
        let limit      = null;
        let limitRange = null;
        let pitch      = null;
        let singular   = null;

        let current = name;
        for (let step = 0; step < DoomSoundCatalog.MAX_CHAIN; step++) {
            const def = this._defs[current];
            if (def === undefined) {
                return null;
            }
            limit      = (limit      ?? def.limit      ?? null);
            limitRange = (limitRange ?? def.limitRange ?? null);
            pitch      = (pitch      ?? def.pitch      ?? null);
            singular   = (singular   ?? def.singular   ?? null);

            if (def.lump !== undefined) {
                lump = def.lump;
                break;
            }
            if (def.alias !== undefined) {
                current = def.alias;
                continue;
            }
            if (def.random !== undefined) {
                current = def.random[Math.floor(Math.random() * def.random.length)];
                continue;
            }

            return null;
        }
        if (lump === null) {
            return null;
        }

        return {
            lump:       lump,
            limit:      (limit ?? WadConstants.SOUND_NEAR_LIMIT),
            limitRange: (limitRange ?? WadConstants.SOUND_NEAR_LIMIT_RANGE),
            pitch:      pitch,
            singular:   (singular === true)
        };
    }
}

;
// === /js/doom/sound/doomSoundSequences.js ===
/**
 * Catalog of the sound sequences (the Hexen-engine SNDSEQ mechanism): parses
 * the SNDSEQ text format — the WAD's own lump when it carries one (Hexen),
 * else the game profile's transcribed text (Heretic's ambient scripts) — into
 * named command lists a DoomSoundSequencePlayer executes.
 *
 * Grammar (zdoom.org/wiki/SNDSEQ): `:Name` opens a sequence, `end` closes it,
 * one command per line, `//` comments; `[Name n Seq …]` blocks define the
 * numbered door/platform groups (parsed and kept for Hexen, unused today).
 * `slot` and `environment` are metadata, not commands: the slot names the
 * random-pick family, the environment number is the one Raven's ambient
 * things (1200+n) address.
 */
class DoomSoundSequences {
    /**
     * @param {string} text SNDSEQ source (lump or profile transcription)
     */
    constructor(text) {
        this._byName        = {};
        this._byEnvironment = {};
        this._groups        = {};
        this._parse(text ?? '');
    }

    /**
     * @param {string} name
     * @returns {object|null} {commands, slot, environment}
     */
    byName(name) {
        return (this._byName[name] ?? null);
    }

    /**
     * @param {number} environment the ambient-thing index (thing 1200+n → n)
     * @returns {string|null} sequence name
     */
    environmentSequence(environment) {
        return (this._byEnvironment[environment] ?? null);
    }

    _parse(text) {
        const lines = text.split('\n');
        let current = null;
        let group   = null;
        for (const raw of lines) {
            const line = raw.replace(/\/\/.*$/, '').trim();
            if (line === '') {
                continue;
            }
            const tokens = line.split(/\s+/);
            if (group !== null) {
                if (tokens[0] === ']') {
                    group = null;
                } else if (tokens.length >= 2) {
                    group[Number(tokens[0])] = tokens[1];
                }
                continue;
            }
            if (line.startsWith('[')) {
                group = {};
                this._groups[tokens[0].slice(1)] = group;
                continue;
            }
            if (line.startsWith(':')) {
                current = {commands: [], slot: null, environment: null};
                this._byName[line.slice(1)] = current;
                continue;
            }
            if (current === null) {
                continue;
            }
            this._parseCommand(current, tokens);
            if (tokens[0] === 'end') {
                current = null;
            }
        }
        for (const [name, sequence] of Object.entries(this._byName)) {
            if (sequence.environment !== null) {
                this._byEnvironment[sequence.environment] = name;
            }
        }
    }

    _parseCommand(sequence, tokens) {
        const op = tokens[0];
        if (op === 'slot') {
            sequence.slot = tokens[1];
            return;
        }
        if (op === 'environment') {
            sequence.environment = Number(tokens[1]);
            return;
        }
        if (op === 'end') {
            return;
        }
        // Numeric arguments stay strings until execution needs them: a sound
        // name and a number both travel as tokens.
        sequence.commands.push({op: op, args: tokens.slice(1)});
    }
}

