            loaderId:   loader.textures().loadFromData(null, flipped),
            width:      dv.getUint16(0, true),
            height:     dv.getUint16(2, true),
            leftOffset: dv.getUint16(0, true) - dv.getInt16(4, true),
            topOffset:  dv.getInt16(6, true)
