// xspeed/yspeed tables apply to worldX/worldZ directly (SQRTHALF LUT).
DoomMonsterMove.SQRTHALF     = 0.7071075439453125;
DoomMonsterMove.XSPEED       = [1, DoomMonsterMove.SQRTHALF, 0, -DoomMonsterMove.SQRTHALF, -1, -DoomMonsterMove.SQRTHALF, 0, DoomMonsterMove.SQRTHALF];
DoomMonsterMove.YSPEED       = [0, DoomMonsterMove.SQRTHALF, 1, DoomMonsterMove.SQRTHALF, 0, -DoomMonsterMove.SQRTHALF, -1, -DoomMonsterMove.SQRTHALF];
// BOOM ORIG_FRICTION_FACTOR (2048/65536) — the normal-ground move factor
DoomMonsterMove.ORIG_FRICTION_FACTOR = 2048 / 65536;
