DoomMonsterMove.CONTACT_EPSILON      = 0.005;
// Unit offsets of the four corners of a body's box, in radius multiples
DoomMonsterMove.BOX_CORNERS          = [[-1, -1], [1, -1], [-1, 1], [1, 1]];
