    /**
     * @param {DoomMonsterSystem} monsters
     * @param {DoomEffectSpawner} effects
     * @param {DoomRandom}        rng
     * @param {object}            rules      profile.monsterDamageRules()
     * @param {DoomLevelStats}    stats      kill counter
     */
