        const turned  = Math.min(boxW / spanY, boxH / spanX);
        const quarter = (turned > upright);
        this._scale   = ((quarter) ? turned : upright);

        const usedW = ((quarter) ? spanY : spanX) * this._scale;
        const usedH = ((quarter) ? spanX : spanY) * this._scale;
