            y:            user.y,
            z:            user.z,
            yaw:          user.yaw,
            pitch:        user.pitch,
            cameraY:      user.getCameraY(),
            lean:         user.getStrafeLean(),
            dead:         user.isDead(),
            energy:       hud.energy,
            armor:        hud.armor,
            maxArmor:     hud.maxArmor,
            armorAbsorb:  hud.armorAbsorb,
