        DoomNetStateCodec._list(w, snapshot.bodies, (body) => DoomNetStateCodec._writeBody(w, body));
        DoomNetStateCodec._list(w, snapshot.bornBodies, (born) => w.u32(born.id).u8(((born.drop) ? 1 : 0)).ascii(born.kind));
