// === /js/doom/doomPlayerRoster.js ===
/**
 * The players of a game, looked up by id, one of them being the local player
 * (the one this device samples and views). A single-player game holds its
 * local player alone.
 */
class DoomPlayerRoster {
    constructor() {
        this._players = new Map();
        this._localId = null;
    }

    add(player) {
        this._players.set(player.getId(), player);

        return this;
    }

    setLocal(player) {
        this.add(player);
        this._localId = player.getId();

        return this;
    }

    /**
     * The local player gives way to another one (a sub's view switching from
     * the main's player to its own).
     *
     * @param {DoomPlayer} player
     */
    replaceLocal(player) {
        this._players.delete(this._localId);

        return this.setLocal(player);
    }

    remove(id) {
        this._players.delete(id);

        return this;
    }

    /**
     * @returns {DoomPlayer}
     */
    getLocal() {
        return this._players.get(this._localId);
    }

    /**
     * @param {int} id
     * @returns {DoomPlayer|null}
     */
    getById(id) {
        return (this._players.get(id) ?? null);
    }

    /**
     * @param {DoomUser} user
     * @returns {DoomPlayer|null} the player whose current body it is
     */
    getByUser(user) {
        for (const player of this._players.values()) {
            if (player.getUser() === user) {
                return player;
            }
        }

        return null;
    }

    /**
     * @returns {DoomPlayer[]} in joining order
     */
    getAll() {
        return Array.from(this._players.values());
    }

    /**
     * @returns {DoomPlayer[]} those whose body is in the running level, in joining order
     */
    getInLevel() {
        return this.getAll().filter((player) => player.isInLevel());
    }
}

