    allowsLevelRestart() {
        return true;
    }

    allowsCheatFullKit() {
        return true;
    }

    allowsScreenSharing() {
        return true;
    }

    allowsCooperative() {
        return true;
    }

    admitsSubPlayers() {
        return false;
    }

    respawnsDeadPlayers() {
        return false;
    }

    leavesPickedItems() {
        return false;
    }

    allowsFriendlyFire() {
        return false;
    }

    scoresFrags() {
        return false;
    }

    showsOtherPlayersOnMap() {
        return true;
    }

    respawnsItems() {
        return false;
    }

    givesDeathmatchWeaponAmmo() {
        return false;
    }

    fragLimit() {
        return null;
    }

    timeLimitMs() {
        return null;
    }

    holdsLevelStart() {
        return false;
    }

